import { useState, useEffect } from 'react';
export function useLocalStorage<T>(key: string, initialValue: T) {
  const [value, setValue] = useState<T>(() => {
    const stored = localStorage.getItem(key);
    return stored ? JSON.parse(stored) : initialValue;
  });
  useEffect(() => {
    localStorage.setItem(key, JSON.stringify(value));
  }, [key, value]);
  return [value, setValue] as const;
}

import { Request, Response } from 'express';
import pdfParse from 'pdf-parse';

export interface ParsedResumeResult {
  text: string;
  numpages: number;
  info: any;
}

export class ResumeParserService {
  public static async parsePDFBuffer(buffer: Buffer): Promise<ParsedResumeResult> {
    if (!buffer || buffer.length === 0) {
      throw new Error('Invalid or empty PDF buffer provided.');
    }
    try {
      const data = await pdfParse(buffer);
      return {
        text: data.text,
        numpages: data.numpages,
        info: data.info,
      };
    } catch (error: any) {
      throw new Error(`Failed to parse PDF document: ${error.message}`);
    }
  }

  public static handleUpload = async (req: Request, res: Response): Promise<void> => {
    try {
      if (!req.file) {
        res.status(400).json({ error: 'No PDF file uploaded.' });
        return;
      }
      const parsedData = await ResumeParserService.parsePDFBuffer(req.file.buffer);
      res.status(200).json({
        success: true,
        filename: req.file.originalname,
        pages: parsedData.numpages,
        extractedText: parsedData.text,
      });
    } catch (err: any) {
      res.status(500).json({ success: false, error: err.message });
    }
  };
}

export interface MatchResult {
  score: number;
  matchedKeywords: string[];
  missingKeywords: string[];
  totalJobKeywords: number;
}

export class KeywordMatcherEngine {
  private static tokenize(text: string): Set<string> {
    const cleaned = text.toLowerCase().replace(/[^\w\s]/g, ' ');
    const stopWords = new Set(['and', 'the', 'to', 'a', 'of', 'in', 'for', 'is', 'on', 'that', 'by', 'this', 'with', 'i', 'you', 'it', 'not', 'or', 'be', 'are']);
    const tokens = cleaned.split(/\s+/).filter(token => token.length > 2 && !stopWords.has(token));
    return new Set(tokens);
  }

  public static calculateMatch(resumeText: string, jobDescriptionText: string): MatchResult {
    const resumeTokens = KeywordMatcherEngine.tokenize(resumeText);
    const jobTokens = KeywordMatcherEngine.tokenize(jobDescriptionText);

    const matchedKeywords: string[] = [];
    const missingKeywords: string[] = [];

    jobTokens.forEach(token => {
      if (resumeTokens.has(token)) {
        matchedKeywords.push(token);
      } else {
        missingKeywords.push(token);
      }
    });

    const totalJobKeywords = jobTokens.size;
    const score = totalJobKeywords > 0 ? Math.round((matchedKeywords.length / totalJobKeywords) * 100) : 0;

    return {
      score,
      matchedKeywords,
      missingKeywords,
      totalJobKeywords,
    };
  }
}
